# envcfg.py

import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env=os.environ):
    config = defaults.copy()

    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(_flatten_dict(toml_config))
        except FileNotFoundError:
            pass

    for key, value in env.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config[env_key] = _coerce_value(value, config.get(env_key))

    return config

def _flatten_dict(d, parent_key='', sep='.'):
    items = {}
    for k, v in d.items():
        new_key = f'{parent_key}{sep}{k}' if parent_key else k
        if isinstance(v, dict):
            items.update(_flatten_dict(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items

def _coerce_value(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for value: {value}')

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'key': 'value'}
    config = load_config(defaults)
    assert config == {'key': 'value'}

def test_toml_file():
    toml_content = b'key = "value"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    config = load_config({}, 'config.toml')
    assert config == {'key': 'value'}


def test_env_variables():
    os.environ['APP__KEY'] = 'value'
    config = load_config({}, env_prefix='APP__')
    assert config == {'key': 'value'}

def test_precedence():
    defaults = {'key': 'default'}
    toml_content = b'key = "toml"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    os.environ['APP__KEY'] = 'env'
    config = load_config(defaults, 'config.toml', env_prefix='APP__')
    assert config == {'key': 'env'}

def test_coercion():
    os.environ['APP__NUMBER'] = '42'
    config = load_config({'number': 0}, env_prefix='APP__')
    assert config == {'number': 42}

def test_missing_toml_file():
    config = load_config({}, 'nonexistent.toml')
    assert config == {}

def test_missing_env_variable():
    with pytest.raises(ConfigError):
        load_config({'key': 'value'}, env_prefix='APP__')

def test_invalid_coercion():
    os.environ['APP__NUMBER'] = 'invalid'
    with pytest.raises(ConfigError):
        load_config({'number': 0}, env_prefix='APP__')
